export type UpcomingFestive = Holiday & { tag: string; at: Date };

/**
 * Every holiday by its next date (today counts), soonest first — one calendar for everyone, never re-ordered by the
 * viewer's country. Holidays without a date left in holidayDates.ts drop out (re-run the generator to extend it).
 */
export function upcomingFestive(now = new Date()): UpcomingFestive[] {
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const out: UpcomingFestive[] = [];
  for (const h of HOLIDAYS) {
    const next = (HOLIDAY_DATES[h.key] ?? []).map((d) => { const [y, m, day] = d.split('-').map(Number); return new Date(y, m - 1, day); }).find((d) => d.getTime() >= today);
    if (next) out.push({ ...h, tag: h.key, at: next });
  }
  return out.sort((a, b) => a.at.getTime() - b.at.getTime());
}
